using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_b5ea3e32854443c098928d997aaf51bf.Auth;

/// <summary>
/// Persists the authentication state from the server into PersistentComponentState
/// so that the WebAssembly client can restore it after the interactive runtime takes over.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly AuthenticationStateProvider _inner;
    private PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public PersistingAuthenticationStateProvider(
        PersistentComponentState persistentState,
        AuthenticationStateProvider inner)
    {
        _persistentState = persistentState;
        _inner = inner;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        _authStateTask ??= _inner.GetAuthenticationStateAsync();
        return _authStateTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var user = authState.User;

        if (user.Identity?.IsAuthenticated == true)
        {
            var data = new AuthenticationStateData
            {
                NameClaimType = ClaimTypes.Name,
                RoleClaimType = ClaimTypes.Role,
                Claims = user.Claims.Select(c => new ClaimData(c)).ToList()
            };

            _persistentState.PersistAsJson(nameof(AuthenticationStateData), data);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_b5ea3e32854443c098928d997aaf51bf.Client;

/// <summary>
/// Reads the persisted authentication state from PersistentComponentState on the client (WebAssembly).
/// This ensures the user's identity and roles survive the prerender-to-interactive handoff.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _anonymous =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<AuthenticationStateData>(
                nameof(AuthenticationStateData), out var data) && data is not null)
        {
            var claims = data.Claims.Select(c => new Claim(c.Type, c.Value)).ToList();
            var identity = new ClaimsIdentity(claims, "PersistentAuth", data.NameClaimType, data.RoleClaimType);
            var user = new ClaimsPrincipal(identity);
            _authStateTask = Task.FromResult(new AuthenticationState(user));
        }
        else
        {
            _authStateTask = _anonymous;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authStateTask;
}

